/**
 * Parses a statement date after normalising the well known noise (extra spaces, optional
 * hyphens, 'JUY' printed instead of 'JUL') found in the statements. Returns null when the
 * given text does not hold a supported date instead of blowing up the whole transaction line.
 */
    public static Date parseStatementDate(String date) {
        if (!date) {
            return null
        }
        try {
            String processedDate = processValue(date.trim())
            SimpleDateFormat dateFormat = dateFormatFromString(processedDate)
            return dateFormat ? dateFormat.parse(processedDate) : null
        } catch (Exception e) {
            log.debug("Unable to resolve the date format of '${date}' ====>>>>>> ${e.message}")
            return null
        }
    }

