 * the account holder changes, hence that rule is the only bank layout specific part of the extraction.
 */
    private
    static void extractBasicInformationFromStatement(ProcessedBankStatementVO processedBankStatementVO,
                                                     List<String> statementIdentifiers, Closure accountHolderNameRule) {
        if (!AppUtil.isValidStatementFile(processedBankStatementVO.processBankStatementCO.textFile, statementIdentifiers)) {
            return
        }
        BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(processedBankStatementVO.processBankStatementCO.textFile), "UTF-8"))
        BasicDetailsResponse basicDetailsResponse = processedBankStatementVO.basicDetails
        String line = ""
        while (line != null) {
            line = reader.readLine()
            if (StringUtils.isBlank(line)) {
                continue
            }
            String accountHolderName = accountHolderNameRule.call(line)
            if (accountHolderName) {
                basicDetailsResponse.accountHolderName = accountHolderName
            } else if (line?.find("[0-9]{3}-[0-9]{6}-[0-9]{3}") && line.find("(?i)Account[\\s]*Number")) {
                String accountNumber = line.find("[0-9]{3}-[0-9]{6}-[0-9]{3}")
                basicDetailsResponse.accountNumber = HelperMethod.getSanitizeAccountNumber(accountNumber)
                break
            }
        }
        processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.PARTIALLY_PARSED
        processedBankStatementVO.statementStatus.message = "Basic details extracted Successfully"
        reader.close()
    }

